local computer=require("computer");local event=require("event");local term=require("term");local config=require("config.config");local gui=require("modules.gui");local flux=require("modules.flux");local me=require("modules.me");local reactors=require("modules.reactors");local players=require("modules.players");local chat=require("modules.chat");local updater=require("modules.updater")
local ok,err=gui.init();if not ok then print(err);return end;chat.start(players);local lastMissing=0
while true do local md=me.update();if md then gui.drawME(md.cpu)end;local fd=flux.update();if fd then gui.drawFlux(fd)end;local rd=reactors.update(me.getFluid());if rd then gui.drawReactors(rd);if rd.missing>0 and rd.missing~=lastMissing then chat.notifyMissing(rd.missing,rd.count,rd.count+rd.missing)end;lastMissing=rd.missing end;local pd,ch=players.update();if pd then gui.drawPlayers(pd);chat.notifyChanges(ch)end;gui.drawButtons();local e={event.pull(config.tickInterval)};if e[1]=="touch"then local a=gui.hitButton(e[3],e[4]);if a=="restart"then computer.shutdown(true)elseif a=="exit"then term.clear();print("Мониторинг остановлен");return elseif a=="update"then term.clear();print("Обновление всего проекта...");local s,m=updater.run();print(m);if s then computer.shutdown(true)else print("Нажмите любую клавишу");event.pull("key_down");gui.init()end end end end
